import {materials} from '../../core/index.js';
import {FACE} from '../../modeling/parts.js';
import {THREE,roundedRect,mesh,hole,solid,ring,box,cylinder} from './geometry.js';
import {spec} from './dimensions.js';
function frontShape(){const s=new THREE.Shape();s.moveTo(-8,-24);s.lineTo(-5.15,-24);s.lineTo(-5.15,-16.1);s.lineTo(5.15,-16.1);s.lineTo(5.15,-24);s.lineTo(8,-24);s.absarc(8,-20,4,-Math.PI/2,0,false);s.lineTo(12,20);s.absarc(8,20,4,0,Math.PI/2,false);s.lineTo(-8,24);s.absarc(-8,20,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-20);s.absarc(-8,-20,4,Math.PI,Math.PI*1.5,false);s.closePath();for(const[x,y]of spec.mounting.centres)hole(s,x,y,2.4);return s;}
function leftShape(){const s=new THREE.Shape();s.moveTo(-8,24);s.absarc(-8,20,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-20);s.absarc(-8,-20,4,Math.PI,Math.PI*1.5,false);s.lineTo(-5.15,-24);s.lineTo(-5.15,-22.9);s.lineTo(-8,-22.9);s.absarc(-8,-20,2.9,-Math.PI/2,-Math.PI,true);s.lineTo(-10.9,20);s.absarc(-8,20,2.9,Math.PI,Math.PI/2,true);s.lineTo(-8,24);s.closePath();return s;}
function relief(parent,material){const frame=new THREE.Group();frame.position.set(0,-19,-3.9);frame.quaternion.copy(FACE.back);frame.name='Original U031 physical unpainted rear M5 relief';parent.add(frame);const glyphs=[];for(const[name,points]of[['M',[[-4.6,-2],[-4.6,2],[-4.1,2],[-2.55,.3],[-1,2],[-.5,2],[-.5,-2],[-1,-2],[-1,1.2],[-2.55,-.45],[-4.1,1.2],[-4.1,-2]]],['5',[[.4,2],[4.5,2],[4.5,1.5],[.95,1.5],[.95,.35],[3.3,.35],[4.2,-.15],[4.5,-.7],[4.5,-1.4],[4.05,-2],[.4,-2],[.4,-1.5],[3.75,-1.5],[3.95,-1.15],[3.95,-.8],[3.7,-.35],[3.15,-.15],[.4,-.15]]]])glyphs.push(mesh(frame,solid(new THREE.Shape(points.map(p=>new THREE.Vector2(...p))),.1),material,[0,0,0],'U031 moulded white '+name+' true material'));return{frame,glyphs};}
export function casing(host){const m=materials.plastic(0xeeeee7,{roughness:.82}),shape=roundedRect(24,48,4);for(const[x,y]of spec.mounting.centres)hole(shape,x,y,2.4);hole(shape,0,-12,1.6);const rear=mesh(host.body,solid(shape,1),m,[0,0,-3.9],'U031 original closed rear skin with real2mount bores and screw opening'),front=mesh(host.body,solid(frontShape(),1),m,[0,0,2.9],'U031 original closed front skin;Grove notch is a true boundary opening'),left=leftShape(),right=new THREE.Shape(left.getPoints(64).map(p=>new THREE.Vector2(-p.x,p.y))),sides=[mesh(host.body,solid(left,5.8),m,[0,0,-2.9],'U031 real closed curved left perimeter wall'),mesh(host.body,solid(right,5.8),m,[0,0,-2.9],'U031 real closed curved right perimeter wall')];
 const top=roundedRect(16,6,.05),slot=roundedRect(1.6,1.25,.1,{cx:-6.8,cy:-.55,path:new THREE.Path()});top.holes.push(slot);const topWall=mesh(host.body,solid(top,1.1).rotateX(Math.PI/2),m,[0,24,0],'U031 top endwall with actual small slot and FrontSide walls'),lowerFloor=box(host.body,[10.3,1.1,1.5],[0,-23.45,-2.15],m,'U031 white bottom casing bridge supports Grove receiving floor'),bosses=[];for(const[x,y]of spec.mounting.centres)bosses.push(mesh(host.body,ring(3.2,2.4,5.8),m,[x,y,-2.9],'U031 physical through bore support sleeve'));const screwBoss=mesh(host.body,ring(1.95,.85,5.8),m,[0,-12,-2.9],'U031 physical central fixed screw support');const posts=[];for(const x of[-8,8])for(const y of[-19,18])posts.push(mesh(host.body,cylinder(.95,.7),m,[x,y,-2.55],'U031 own inferred rear-to-PCB support post'));
 const slotBacking=box(host.body,[2.8,.9,1.7],[-6.8,21.8,-.55],materials.plastic(0x8e9285,{roughness:.9}),'U031 fixed dark internal slot backing;function unconfirmed'),slotSupport=box(host.body,[2.8,1.4,.2],[-6.8,21.55,-1.3],m,'U031 fixed small-slot carrier seated on actualPCB');return{front,rear,sides,topWall,lowerFloor,bosses,screwBoss,posts,slotBacking,slotSupport,relief:relief(host.body,m)};}
export function fixing(host){const metal=materials.metal(0xb0b3a9,{roughness:.45}),s=new THREE.Shape();s.absarc(0,0,1.4,0,Math.PI*2,false);const p=new THREE.Path();for(let i=0;i<6;i++){const a=i*Math.PI/3;i?p.lineTo(Math.cos(a)*.56,Math.sin(a)*.56):p.moveTo(Math.cos(a)*.56,Math.sin(a)*.56);}p.closePath();s.holes.push(p);const head=mesh(host.body,solid(s,.58),metal,[0,-12,-3.88],'U031 actual fixed rear screw head with reconstructed hex well'),floor=mesh(host.body,cylinder(.55,.08),materials.plastic(0x484c42),[0,-12,-3.34],'U031 true recessed hex drive floor'),washer=mesh(host.body,ring(1.65,.7,.3),metal,[0,-12,-3.3],'U031 real bearing face at rear support'),shank=mesh(host.body,cylinder(.7,5.7),metal,[0,-12,-.15],'U031 retained screw shank;static,no joint');return{head,floor,washer,shank};}
